import{_ as l,H as E,f as i,i as B}from"./chunks/framework.BH2BK_3i.js";const c=JSON.parse('{"title":"05-网盘系统设计：万亿GB网盘如何实现秒传与限速？","description":"","frontmatter":{},"headers":[{"level":2,"title":"需求分析","slug":"需求分析","link":"#需求分析","children":[{"level":3,"title":"负载指标估算","slug":"负载指标估算","link":"#负载指标估算","children":[]},{"level":3,"title":"10亿× 1TB = 10亿TB","slug":"_10亿×-1tb-10亿tb","link":"#_10亿×-1tb-10亿tb","children":[]},{"level":3,"title":"2亿× 4 ÷ （24 × 60 × 60）≈1万","slug":"_2亿×-4-÷-24-×-60-×-60-≈1万","link":"#_2亿×-4-÷-24-×-60-×-60-≈1万","children":[]},{"level":3,"title":"1万× 1MB = 10GB/s = 80Gb/s","slug":"_1万×-1mb-10gb-s-80gb-s","link":"#_1万×-1mb-10gb-s-80gb-s","children":[]},{"level":3,"title":"非功能需求","slug":"非功能需求","link":"#非功能需求","children":[]}]},{"level":2,"title":"概要设计","slug":"概要设计","link":"#概要设计","children":[{"level":3,"title":"2","slug":"_2","link":"#_2","children":[]},{"level":3,"title":"×","slug":"×","link":"#×","children":[]},{"level":3,"title":"4MB = 180亿PB","slug":"_4mb-180亿pb","link":"#_4mb-180亿pb","children":[]}]},{"level":2,"title":"详细设计","slug":"详细设计","link":"#详细设计","children":[{"level":3,"title":"元数据库设计","slug":"元数据库设计","link":"#元数据库设计","children":[]},{"level":3,"title":"限速","slug":"限速","link":"#限速","children":[]},{"level":3,"title":"秒传","slug":"秒传","link":"#秒传","children":[]}]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"李智慧·高并发架构实战课/05-网盘系统设计：万亿GB网盘如何实现秒传与限速？.md","filePath":"李智慧·高并发架构实战课/05-网盘系统设计：万亿GB网盘如何实现秒传与限速？.md","lastUpdated":1795558450000}'),t={name:"李智慧·高并发架构实战课/05-网盘系统设计：万亿GB网盘如何实现秒传与限速？.md"};function a(o,e,s,n,p,r){return E(),i("div",null,[...e[0]||(e[0]=[B('<h1 id="_05-网盘系统设计-万亿gb网盘如何实现秒传与限速" tabindex="-1">05-网盘系统设计：万亿GB网盘如何实现秒传与限速？ <a class="header-anchor" href="#_05-网盘系统设计-万亿gb网盘如何实现秒传与限速" aria-label="Permalink to &quot;05-网盘系统设计：万亿GB网盘如何实现秒传与限速？&quot;">​</a></h1><p>你好，我是李智慧。</p><p>网盘，又称云盘，是提供文件托管和文件上传、下载服务的网站（File hosting service）。人们通过网盘保管自己拍摄的照片、视频，通过网盘和他人共享文件，已经成为了一种习惯。我们准备开发一个自己的网盘应用系统，应用名称为“DBox”。</p><p>十几年前曾经有个段子，技术人员对老板说：您不能在公司电脑打开您家里电脑的文件，再贵的电脑也不能。事实上，随着网盘技术的成熟，段子中老板的需求已经成为现实：网盘可以自动将家里电脑的文件同步到公司电脑，老板可以在公司的电脑打开家里电脑的文件了。</p><p>网盘的主要技术挑战是海量数据的高并发读写访问。用户上传的海量数据如何存储？如何避免部分用户频繁读写文件，消耗太多资源，而导致其他的用户体验不佳？我们看下 DBox 的技术架构以及如何解决这些问题。</p><h2 id="需求分析" tabindex="-1">需求分析 <a class="header-anchor" href="#需求分析" aria-label="Permalink to &quot;需求分析&quot;">​</a></h2><p>DBox 的核心功能是提供文件上传和下载服务。基于核心功能，DBox 需要在服务器端保存这些文件，并在下载和上传过程中实现断点续传。也就是说，如果上传或下载过程被中断了，恢复之后，还能从中断的地方重新上传或者下载，而不是从头再来。</p><p>DBox 还需要实现文件共享的需求。使用 DBox 的不同用户之间可以共享文件，一个用户上传的文件共享给其他用户后，其他用户也可以下载这个文件。</p><p>此外，网盘是一个存储和网络密集型的应用，用户文件占据大量硬盘资源，上传、下载需要占用大量网络带宽，并因此产生较高的运营成本。所以用户体验需要向付费用户倾斜，DBox 需要对上传和下载进行流速控制，保证付费用户得到更多的网络资源。DBox 用例图如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/1.png" alt=""></a></p><h3 id="负载指标估算" tabindex="-1">负载指标估算 <a class="header-anchor" href="#负载指标估算" aria-label="Permalink to &quot;负载指标估算&quot;">​</a></h3><p>DBox 的设计目标是支持 10 亿用户注册使用，免费用户最大可拥有 1TB 存储空间。预计日活用户占总用户的 20%，即 2 亿用户。每个活跃用户平均每天上传、下载 4 个文件。</p><p>DBox 的存储量、吞吐量、带宽负载估算如下。</p><ul><li>总存储量理论上，总存储空间估算为 10 亿 TB，即 1 万亿 GB。</li></ul><h3 id="_10亿×-1tb-10亿tb" tabindex="-1">10亿× 1TB = 10亿TB <a class="header-anchor" href="#_10亿×-1tb-10亿tb" aria-label="Permalink to &quot;10亿× 1TB = 10亿TB&quot;">​</a></h3><p>但考虑到大多数用户并不会完全用掉这个空间，还有很多用户存储的文件其实是和别人重复的（电影、电子书、软件安装包等），真正需要的存储空间大约是这个估算值的 10%，即 1 亿TB。</p><ul><li>QPS系统需要满足的平均 QPS 约为 10000。</li></ul><h3 id="_2亿×-4-÷-24-×-60-×-60-≈1万" tabindex="-1">2亿× 4 ÷ （24 × 60 × 60）≈1万 <a class="header-anchor" href="#_2亿×-4-÷-24-×-60-×-60-≈1万" aria-label="Permalink to &quot;2亿× 4 ÷ （24 × 60 × 60）≈1万&quot;">​</a></h3><p>高峰期 QPS 约为平均 QPS 的两倍，即 2 万。</p><ul><li>带宽负载每次上传下载文件平均大小 1MB，所以需要网络带宽负载 10GB/s，即 80Gb/s。</li></ul><h3 id="_1万×-1mb-10gb-s-80gb-s" tabindex="-1">1万× 1MB = 10GB/s = 80Gb/s <a class="header-anchor" href="#_1万×-1mb-10gb-s-80gb-s" aria-label="Permalink to &quot;1万× 1MB = 10GB/s = 80Gb/s&quot;">​</a></h3><p>同样，高峰期带宽负载为 160Gb/s。</p><h3 id="非功能需求" tabindex="-1">非功能需求 <a class="header-anchor" href="#非功能需求" aria-label="Permalink to &quot;非功能需求&quot;">​</a></h3><ol><li><p>大数据量存储：10 亿注册用户，1000 亿个文件，约 1 亿 TB 的存储空间。</p></li><li><p>高并发访问：平均 1 万 QPS，高峰期 2 万 QPS。</p></li><li><p>大流量负载：平均网络带宽负载 80Gb/S，高峰期带宽负载 160Gb/s。</p></li><li><p>高可靠存储：文件不丢失，持久存储可靠性达到 99.9999% ，即 100 万个文件最多丢失（或损坏）1 个文件。</p></li><li><p>高可用服务：用户正常上传、下载服务可用性在 99.99% 以上，即一年最多 53 分钟不可用。</p></li><li><p>数据安全性：文件需要加密存储，用户本人及共享文件外，其他人不能查看文件内容。</p></li><li><p>不重复上传：相同文件内容不重复上传，也就是说，如果用户上传的文件内容已经被其他用户上传过了，该用户不需要再上传一次文件内容，进而实现“秒传”功能。从用户视角来看，不到一秒就可以完成一个大文件的上传。</p></li></ol><h2 id="概要设计" tabindex="-1">概要设计 <a class="header-anchor" href="#概要设计" aria-label="Permalink to &quot;概要设计&quot;">​</a></h2><p>网盘设计的关键是元数据与文件内容的分离存储与管理。所谓文件元数据就是文件所有者、文件属性、访问控制这些文件的基础信息，事实上，传统文件系统也是元数据与文件内容分离管理的，比如 Linux 的文件元数据记录在文件控制块 FCB 中，Windows 的文件元数据记录在文件分配表 FAB 中，Hadoop 分布式文件系统 HDFS 的元数据记录在 NameNode 中。</p><p>而 DBox 是将元信息存储在数据库中，文件内容则使用另外专门的存储体系。但是由于 DBox是一个互联网应用，出于安全和访问管理的目的，并不适合由客户端直接访问存储元数据的数据库和存储文件内容的存储集群，而是通过 API 服务器集群和数据块服务器集群分别进行访问管理。整体架构如下图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/2.png" alt=""></a></p><p>对于大文件，DBox 不会上传、存储一整个的文件，而是将这个文件进行切分，变成一个个单独的 Block，再将它们分别上传并存储起来。</p><p>这样做的核心原因是，DBox 采用对象存储作为最终的文件存储方案，而对象存储不适合存储大文件，需要进行切分。而大文件进行切分还带来其他的好处：可以以 Block 为单位进行上传和下载，提高文件传输速度；客户端或者网络故障导致文件传输失败，也只需要重新传输失败的 Block 就可以，进而实现断点续传功能。</p><p>Block 服务器就是负责 Block 上传和管理的。客户端应用程序根据 API 服务器的返回指令，将文件切分成一些 Block，然后将这些 Block 分别发送给 Block 服务器，Block 服务器再调用对象存储服务器集群，将 Block 存储在对象存储服务器中（DBox 选择 Ceph 作为对象存储）。</p><p>用户上传文件的时序图如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/3.png" alt=""></a></p><p>用户上传文件时，客户端应用程序收集文件元数据，包括文件名、文件内容 MD5、文件大小等等，并根据文件大小计算 Block 的数量（DBox 设定每个 block 大小 4MB），以及每个 Block的 MD5 值。</p><p>然后客户端应用程序将全部元数据（包括所有 Block 的 MD5 值列表）发送给 API 服务器。API 服务器收到文件元数据后，为每个 Block 分配全局唯一的 BlockID（BlockID 为严格递增</p><ul><li>64</li></ul><h3 id="_2" tabindex="-1">2 <a class="header-anchor" href="#_2" aria-label="Permalink to &quot;2&quot;">​</a></h3><h3 id="×" tabindex="-1">× <a class="header-anchor" href="#×" aria-label="Permalink to &quot;×&quot;">​</a></h3><h3 id="_4mb-180亿pb" tabindex="-1">4MB = 180亿PB <a class="header-anchor" href="#_4mb-180亿pb" aria-label="Permalink to &quot;4MB = 180亿PB&quot;">​</a></h3><p>的 64 位正整数，总可记录数据大小</p><ul><li>，足以满足 DBox 的应用场</li></ul><p>景）。</p><p>下一步，API 服务器将文件元数据与 BlockID 记录在数据库中，并将 BlockID 列表和应用程序可以连接的 Block 服务器列表返回客户端。客户端连接 Block 服务器请求上传 Block，Block服务器连接 API 服务器进行权限和文件元数据验证。验证通过后，客户端上传 Block 数据，Block 服务器再次验证 Block 数据的 MD5 值，确认数据完整后，将 BlockID 和 Block 数据保存到对象存储集群 Ceph 中。</p><p>类似的，用户下载文件的时序图如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/4.png" alt=""></a></p><p>客户端程序访问 API 服务器，请求下载文件。然后 API 服务器会查找数据库，获得文件的元数据信息，再将元数据信息中的文件 BlockID 列表及可以访问的 Block 服务器列表返回给客户端。</p><p>下一步，客户端访问 Block 服务器，请求下载 Block。Block 服务器验证用户权限后，从 Ceph中读取 Block 数据，返回给客户端，客户端再将返回的 Block 组装为文件。</p><h2 id="详细设计" tabindex="-1">详细设计 <a class="header-anchor" href="#详细设计" aria-label="Permalink to &quot;详细设计&quot;">​</a></h2><p>为解决网盘的三个重要问题：元数据如何管理？网络资源如何向付费用户倾斜？如何做到不重复上传？DBox 详细设计将关注元数据库、上传下载限速、秒传的设计实现。</p><h3 id="元数据库设计" tabindex="-1">元数据库设计 <a class="header-anchor" href="#元数据库设计" aria-label="Permalink to &quot;元数据库设计&quot;">​</a></h3><p>元数据库表结构设计如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/5.png" alt=""></a></p><p>从图中可以看出，元数据库表结构中主要包括三个表，分别是 User 用户表、File 文件表和Block 数据块表，表的用途和包含的主要字段如下：</p><ol><li><p>User 用户表记录用户基本信息：用户名、创建时间、用户类型（免费、VIP）、用户已用空间、电话号码、头像等等。</p></li><li><p>File 文件表记录文件元信息：文件名、是否为文件夹、上级文件夹、文件 MD5、创建时间、文件大小、文件所属用户、是否为共享文件等。</p></li><li><p>Block 数据块表记录 Block 数据，包括 BlockID、Block MD5、对应文件等。</p></li></ol><p>其中，User 表和 File 表为一对多的关系，File 表和 Block 表也是一对多的关系。</p><p>这 3 种表的记录数都是百亿级以上，所以元数据表采用分片的关系数据库存储。</p><p>因为查询的主要场景是根据用户 ID 查找用户信息和文件信息，以及根据文件 ID 查询 block 信息，所以 User 和 File 表都采用 user_id 作为分片键，Block 表采用 file_id 作为分片键。</p><h3 id="限速" tabindex="-1">限速 <a class="header-anchor" href="#限速" aria-label="Permalink to &quot;限速&quot;">​</a></h3><p>DBox 根据用户付费类型决定用户的上传、下载速度。而要控制上传、下载速度，可以通过限制并发 Block 服务器数目，以及限制 Block 服务器内的线程数来实现。</p><p>具体过程是，客户端程序访问 API 服务器，请求上传、下载文件的时候，API 服务器可以根据用户类型，决定分配的 Block 服务器数目和 Block 服务器内的服务线程数，以及每个线程的上传、下载速率。</p><p>Block 服务器会根据 API 服务器的返回值，来控制客户端能够同时上传、下载的 Block 数量以及传输速率，以此对不同用户进行限速。</p><h3 id="秒传" tabindex="-1">秒传 <a class="header-anchor" href="#秒传" aria-label="Permalink to &quot;秒传&quot;">​</a></h3><p>秒传是用户快速上传文件的一种功能。</p><p>事实上，网盘保存的很多文件，内容其实是重复的，比如电影、电子书等等。一方面，重复上传这些文件会加大网盘的存储负载压力；另一方面，每次都要重新上传重复的内容，会导致用户网络带宽的浪费和用户等待时间过长的问题。</p><p>所以，在设计中，物理上相同的文件，DBox 只会保存一份。用户每次上传文件时，DBox 都会先在客户端计算文件的 MD5 值，再根据 MD5 值判断该文件是否已经存在。对于已经存在的文件，只需要建立用户文件和该物理文件的关联即可，并不需要用户真正上传该文件，这样就可以实现秒传的功能。</p><p>但是，计算 MD5 可能会发生 Hash 冲突，也就是不同文件算出来的 MD5 值是相同的，这样会导致 DBox 误判，将本不相同的文件关联到一个物理文件上。不但会使上传者丢失自己的文件，还会被黑客利用：上传一个和目标文件 MD5 相同的文件，然后就可以下载目标文件了。</p><p>所以，DBox 需要通过更多信息判断文件是否相同：只有文件长度、文件开头 256KB 的 MD5值、文件的 MD5 值，三个值都相同，才会认为文件相同。当文件长度小于 256KB，则直接上传文件，不启用秒传功能。</p><p>为此，我们需要将上面的元数据库表结构进行一些改动，将原来的 File 表拆分成物理文件表Physics_File 和逻辑文件表 Logic_File。其中，Logic_File 记录用户文件的元数据，并和物理文件表 Physics_File 建立多对 1 关联关系，而 Block 表关联的则是 Physics_File 表，如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E6%9D%8E%E6%99%BA%E6%85%A7%C2%B7%E9%AB%98%E5%B9%B6%E5%8F%91%E6%9E%B6%E6%9E%84%E5%AE%9E%E6%88%98%E8%AF%BE/images/05-%25E7%25BD%2591%25E7%259B%2598%25E7%25B3%25BB%25E7%25BB%259F%25E8%25AE%25BE%25E8%25AE%25A1/6.png" alt=""></a></p><p>Physics_File 中字段 md5 和 256kmd5 字段分别记录了文件 MD5 和文件头 256KB 的 MD5 数据，而 size 记录了文件长度，只有这三个字段都相同才会启用秒传。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>我们在需求分析中讨论过，DBox 需要支持大数据量存储、高并发访问、高可用服务、高可靠存储等非功能需求。事实上，对于网盘应用而言，元数据 API 服务其实和一般的高并发互联网系统网关没有太大差别。真正有挑战的是海量文件的高可用存储，而这一挑战，在 DBox 中，被委托给了分布式对象存储 Ceph 来完成。而 Ceph 本身设计就是支持大数据量存储、高并发访问、高可用服务、高可靠存储的。</p><p>架构师按照职责，可以分成两种，一种是应用系统架构师，负责设计、开发类似网盘、爬虫这样的应用系统；另一种是基础设施架构师，负责设计、开发类似 Ceph、HDFS 这样的基础设施系统。</p><p>应用架构师需要掌握的技术栈更加广泛，要能够掌握各种基础设施技术的特性，并能根据业务特点选择最合适的方案；而基础设施架构师需要的技术栈更加深入，需要掌握计算机软硬件更深入的知识，才能开发出一个稳定的基础技术产品。</p><p>当然，最好的架构师应该是技术栈既广泛又深入，既能灵活应用各种基础设施来开发应用系统，也能在需要的时候自己动手开发新的基础设施系统。</p><p>我们专栏大部分案例都是关于应用的，但是也不乏关于编程框架、限流器、安全防火墙、区块链等基础设施的案例。你也可以在学习的过程中，感受下这两种系统的设计方案和技术关键点的不同。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>网盘元数据存储采用分片的关系数据库方案，查询目录和文件都比较简单，但是性能也比较差。而且文件表按用户 ID 分片，如果某个用户创建大量文件，还会导致分片不均衡，你有什么优化的手段和方法吗？</p><p>欢迎在评论区分享你的思考，或者提出对这个设计文档的评审意见，我们共同进步。</p>',79)])])}const b=l(t,[["render",a]]);export{c as __pageData,b as default};
